-- Disposable PostgreSQL CI database ONLY. Never run this fixture in production.
CREATE ROLE anon NOLOGIN;
CREATE ROLE authenticated NOLOGIN;
CREATE SCHEMA auth;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE TABLE auth.identities(id uuid PRIMARY KEY);
CREATE TABLE public.profiles(id uuid PRIMARY KEY, role text, first_name text, last_name text, campus text, college text, year_level text, affiliation text, privacy_acknowledged_at timestamptz);
CREATE TABLE public.opportunities(id uuid PRIMARY KEY);
CREATE TABLE public.bookmarks(id uuid PRIMARY KEY);
CREATE TABLE public.assistance_requests(id uuid PRIMARY KEY);
CREATE TABLE public.opportunity_revisions(id uuid PRIMARY KEY);
CREATE TABLE public.opportunity_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), opportunity_id uuid, user_id uuid, issue_type text, description text, status text DEFAULT 'OPEN');
CREATE TABLE public.site_feedback(id uuid PRIMARY KEY);
CREATE TABLE public.activity_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz DEFAULT now(), actor_id uuid, entity text, entity_id uuid, action text, details text);
CREATE TABLE public.goid_user_preferences(user_id uuid PRIMARY KEY, answers jsonb, updated_at timestamptz);
CREATE TABLE public.app_settings(id uuid PRIMARY KEY);
CREATE TABLE public.goid_notifications(id uuid PRIMARY KEY);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT '00000000-0000-0000-0000-000000000001'::uuid $$;
CREATE FUNCTION public.neu_role() RETURNS text LANGUAGE sql AS $$ SELECT 'student'::text $$;
CREATE FUNCTION public.goid_valid_college(text,text) RETURNS boolean LANGUAGE sql AS $$ SELECT true $$;
CREATE FUNCTION public.goid_update_profile(jsonb) RETURNS void LANGUAGE plpgsql AS $$ BEGIN RETURN; END; $$;
CREATE FUNCTION public.goid_archive_opportunity(uuid,text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN RETURN; END; $$;
CREATE FUNCTION public.goid_emit(uuid,text,text,text,text,text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN RETURN; END; $$;
